package reactor.core.publisher; import java.util.*; import java.util.function.*; import java.util.concurrent.Callable; import java.time.Duration; import reactor.core.scheduler.Scheduler; public abstract class Mono<T> { public static <T> Mono<T> just(T v){throw new UnsupportedOperationException();} public static <T> Mono<T> fromCallable(Callable<? extends T> c){throw new UnsupportedOperationException();} public abstract Mono<T> defaultIfEmpty(T t); public abstract Mono<T> onErrorReturn(T t); public abstract Mono<T> onErrorResume(Function<? super Throwable,? extends Mono<? extends T>> f); public abstract <R> Mono<R> flatMap(Function<? super T,? extends Mono<? extends R>> f); public abstract Mono<T> subscribeOn(Scheduler s); public abstract T block(Duration d); }